import{_ as o,o as r,c as n,ag as s}from"./chunks/framework.DzGOF12C.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"시대적 배경","slug":"시대적-배경","link":"#시대적-배경","children":[]},{"level":2,"title":"선종이란?","slug":"선종이란","link":"#선종이란","children":[]},{"level":2,"title":"지눌은 어떤 삶을 살았는가","slug":"지눌은-어떤-삶을-살았는가","link":"#지눌은-어떤-삶을-살았는가","children":[]},{"level":2,"title":"지눌의 사상","slug":"지눌의-사상","link":"#지눌의-사상","children":[{"level":3,"title":"회광반조(廻光反照)","slug":"회광반조-廻光反照","link":"#회광반조-廻光反照","children":[]},{"level":3,"title":"깨달음에 이르는 세 가지 길(三種禪門)","slug":"깨달음에-이르는-세-가지-길-三種禪門","link":"#깨달음에-이르는-세-가지-길-三種禪門","children":[]},{"level":3,"title":"돈오점수(頓悟漸修)","slug":"돈오점수-頓悟漸修","link":"#돈오점수-頓悟漸修","children":[]}]},{"level":2,"title":"이후 조선 불교","slug":"이후-조선-불교","link":"#이후-조선-불교","children":[]}],"relativePath":"philosophy/Korean-Philosophy/05. 지눌과 선교 통합.md","filePath":"philosophy/Korean-Philosophy/05. 지눌과 선교 통합.md"}'),a={name:"philosophy/Korean-Philosophy/05. 지눌과 선교 통합.md"};function e(l,t,g,i,h,p){return r(),n("div",null,[...t[0]||(t[0]=[s('<h2 id="시대적-배경" tabindex="-1">시대적 배경 <a class="header-anchor" href="#시대적-배경" aria-label="Permalink to &quot;시대적 배경&quot;">​</a></h2><p>신라 말~고려 초, 왕권(교종)이 약화되며 호족(선종) 세력이 강성해지고, 신비주의 사상(도참사상, 궁예의 미륵신앙 등)이 유행함. 삼국시대~통일신라의 불교는 경전을 통해 깨달음을 얻으려는 <strong>교종</strong> 중심이었으나, 왕권이 약화되고 나라가 혼란스러워지면서 이러한 시대적 분위기가 선종이 정착되는 기반을 형성함.</p><h2 id="선종이란" tabindex="-1">선종이란? <a class="header-anchor" href="#선종이란" aria-label="Permalink to &quot;선종이란?&quot;">​</a></h2><p>선종의 계보는 <strong>염화미소</strong>(拈華微笑) 고사에서 시작하여 가섭 — (달마: 520년 북위에 전래, 1조) — 5조 홍인 — 6조 혜능(『육조단경』)으로 이어짐. 선종의 특징은 ①<strong>이심전심</strong>(以心傳心, 마음에서 마음으로 전함), ②<strong>불립문자</strong>(不立文字, 敎外別傳, 문자에 의지하지 않고 가르침 밖에서 따로 전함), ③<strong>직지인심</strong>(直指人心, 사람의 마음을 곧바로 가리킴), ④<strong>견성성불</strong>(見性成佛, 본성을 보아 부처를 이룸)로 요약됨.</p><p>이를 잘 보여주는 비유가 &#39;달과 손가락&#39;이다 — 달을 찾은 사람은 달을 찾지 못한 사람을 위해 손가락으로 달의 위치를 알려준다. 달은 진리 자체이고 손가락은 그 진리에 이르는 문자적 수단일 뿐이다. 손가락의 도움으로 달을 찾았다면 손가락은 잊어야 하지만, 많은 수행자들이 오히려 수단인 손가락(경전과 언어)에 집착하는 경향을 보였음.</p><h2 id="지눌은-어떤-삶을-살았는가" tabindex="-1">지눌은 어떤 삶을 살았는가 <a class="header-anchor" href="#지눌은-어떤-삶을-살았는가" aria-label="Permalink to &quot;지눌은 어떤 삶을 살았는가&quot;">​</a></h2><p>지눌(1158~1210, 시호 <strong>불일보조</strong>, 호 <strong>목우자</strong>)은 무신정권기(1170~1270), 특히 최충헌 집권기의 선종 개혁가. 당시 불교계는 사원경제의 비대화, 명리 추구, 수행의 약화, 교단의 세속화·기복화, 계율의 형식화, 교종·선종 간 알력 등 폐단이 누적되어 있었고 내부 개혁 요구가 고조됨.</p><p>1165년(8세) 출가, 1182년 승과에 급제했으나 절로 돌아가지 않고 뜻이 맞는 이들과 결사체를 조직하여 <strong>선교(禪敎) 통합</strong>의 필요성을 자각함. 1188년 팔공산 거조사에서 **정혜사(定慧社)**를 조직하고 『권수정혜결사문』을 발표, 이후 1200년 송광산 길상사로 옮겨 &quot;중생을 떠나서는 부처가 존재할 수 없다&quot;고 설파하며 <strong>돈오점수</strong>와 <strong>정혜쌍수</strong>를 주장하고, 선(禪)을 체(體)로 교(敎)를 용(用)으로 삼아 선·교의 통합을 추구함. 주요 저서로 『진심직설』, 『목우자수심결』, 『계초심학입문』, 『원돈성불론』, 『간화결의론』, 『법집별행록절요병입사기』 등이 있음.</p><p><strong>왜 절로 가지 않고 결사체를 조직했는가?</strong> 첫째, 좌선만 중시하는 당시 불교 풍토에 대한 비판 — 손가락(문자·언어의 가르침)을 지나치게 도외시한 나머지 많은 승려들이 정작 달(진리)이 어디에 있는지조차 모른 채 2, 30년을 앉아 수행하고도 깨치지 못하는 상황을 우려함. 그래서 선승임에도 다수의 저술을 남김. 둘째, 지적 알음알이(교외별전이 강조하는 언어 이상의 세계)에 대한 병통의 극복 — 달이 아닌 손가락에만 집착하는 조사들이 많았던 데 대해 올바른 깨달음의 길을 제시하고자 함.</p><p><strong>십우도(尋牛圖·목우자십도)<strong>는 지눌의 『목우자수심결』을 도상화한 것으로, 소를 찾는 동자의 여정을 통해 선 수행의 단계를 비유함. ①</strong>심우</strong>(소를 찾아 나섬 — 수행의 입문), ②<strong>견적</strong>(소의 발자국을 봄 — 본성의 자취를 느끼기 시작함), ③<strong>견우</strong>(소를 발견함 — 사물의 근원을 보기 시작함), ④<strong>득우</strong>(소를 잡음 — 견성에 이르렀으나 아직 번뇌가 남아 있어 더 수련이 필요함), ⑤<strong>목우</strong>(소를 길들임 — 삼독을 지워나감), ⑥<strong>기우귀가</strong>(소를 타고 집으로 돌아옴 — 무애의 자유로운 단계), ⑦<strong>망우존인</strong>(소를 잊고 사람만 남음 — 방편이었던 소는 잊어야 함), ⑧<strong>인우구망</strong>(소와 사람 모두 잊음 — 텅 빈 원으로 표현되는 공의 깨달음), ⑨<strong>반본환원</strong>(근원으로 돌아옴 — 산은 산대로 물은 물대로 있는 그대로 보는 참된 지혜), ⑩<strong>입전수수</strong>(저잣거리에 들어가 중생을 제도함 — 이타행의 실천).</p><h2 id="지눌의-사상" tabindex="-1">지눌의 사상 <a class="header-anchor" href="#지눌의-사상" aria-label="Permalink to &quot;지눌의 사상&quot;">​</a></h2><h3 id="회광반조-廻光反照" tabindex="-1">회광반조(廻光反照) <a class="header-anchor" href="#회광반조-廻光反照" aria-label="Permalink to &quot;회광반조(廻光反照)&quot;">​</a></h3><p>&quot;외부로 향하는 마음의 빛을 안으로 돌이켜 비추어라.&quot; 깨닫지 못하게 하는 것도 마음이지만 깨닫게 하는 것도 마음이며, 마음을 통하지 않고서는 결코 깨달을 수 없다(&quot;因地而敗者 因地而起&quot;). &quot;부처가 곧 마음이요, 자기 마음이 곧 부처의 마음이다&quot;(『진심직설』)라는 말처럼 지눌은 **진심(眞心)**을 깨닫는 것을 핵심 과제로 봄.</p><p><strong>진심의 두 측면</strong>: 진심에는 **자성용(自性用)**과 <strong>수연용(隨緣用)</strong> 두 종류의 작용이 있음. 청동거울에 비유하면 청동의 질(재질)은 자성의 체이고, 청동의 밝음은 자성의 용이며, 그 밝은 면에 비친 상은 인연을 따르는 용이다. 마찬가지로 사람 마음의 항상 고요함(常寂)은 자성의 체, 마음의 앎(常知)은 자성의 용, 그 앎이 분별하는 행위들은 인연에 따른 용이다. 거울이 대상에 따라 다른 상을 맺는 것이 <strong>수연응용</strong>(隨緣應用, 인연 따라 대상에 대응해 일어나는 마음의 작용)이라면, 애초에 무엇이든 비출 수 있는 거울 자체의 성질은 <strong>자성본용</strong>(自性本用, 인연과 무관하게 무엇을 알 수 있는 마음 본래의 성질=영지靈知)이다. 지눌은 마음의 본성(자성본용=영지) 자체는 지각(볼) 수 없다고 본다 — 눈이 자기 자신을 볼 수 없는 것과 같은 이치. 다만 분별심(수연응용)을 멈추어 마음에 드러난 온갖 상을 지워버리면, 이미 자신이 마음의 영지를 갖고 있다는 깨달음에 이를 수 있음 — 이 지점에서 부처와 범부는 다를 바 없어진다(&quot;나도 곧 부처이다&quot;).</p><h3 id="깨달음에-이르는-세-가지-길-三種禪門" tabindex="-1">깨달음에 이르는 세 가지 길(三種禪門) <a class="header-anchor" href="#깨달음에-이르는-세-가지-길-三種禪門" aria-label="Permalink to &quot;깨달음에 이르는 세 가지 길(三種禪門)&quot;">​</a></h3><ul><li><strong>원돈신해문(圓頓信解門)</strong>: 화엄의 교리(원만한 진리)를 믿고 이해하여 일순간 깨달음의 세계로 들어가는 길 — <strong>돈오</strong>에 해당.</li><li><strong>성적등지문(惺寂等持門)</strong>: 선을 공부할 때 마음이 성성(惺惺, 혜)하면서도 적적(寂寂, 정)함을 함께 유지하는 길, 즉 <strong>정혜쌍수문</strong> — <strong>점수</strong>에 해당.</li><li><strong>간화경절문(看話徑截門)</strong>: 화두를 통한 직접적 깨달음의 길 — <strong>증오</strong>에 해당.</li></ul><h3 id="돈오점수-頓悟漸修" tabindex="-1">돈오점수(頓悟漸修) <a class="header-anchor" href="#돈오점수-頓悟漸修" aria-label="Permalink to &quot;돈오점수(頓悟漸修)&quot;">​</a></h3><p>돈오점수는 남종(혜능)의 <strong>돈오</strong>와 북종(신수)의 <strong>점수</strong>를 통합한 것. 신수는 &quot;몸은 보리수요 마음은 맑은 거울과 같으니, 항상 부지런히 닦아 먼지가 앉지 않게 하라&quot;(부지런히 먼지를 닦는 노력을 중시)고 했고, 혜능은 &quot;보리는 본래 나무가 아니고 맑은 거울 또한 대가 아니다. 본래 아무것도 없는데 어디에 먼지가 앉겠는가&quot;(본래 공한 마음을 단박에 깨닫는 것을 중시)라고 답함.</p><p>지눌은 깨달음(悟)을 **해오(解悟)**와 **증오(證悟)**로 구분한다 — 해오는 수행 이전에 언어를 통해 얻는 깨달음, 증오는 수행 이후 화두 등을 통해 언어를 초월하여 얻는 깨달음. 지눌이 &quot;돈오&quot;를 선의 시작으로 제시할 때 이는 뒤에 점수가 따라야 하는 <strong>해오</strong>를 뜻함 — 즉 먼저 마음의 본체(공적영지)가 나에게도 있음을 언어적으로 이해(해오=돈오)한 뒤, 이 인식(앎)과 실천(행위) 사이의 간극을 메우기 위해 <strong>점수</strong>(정혜쌍수)의 과정이 필요하다는 것이 지눌 사상의 핵심 구도다.</p><p><strong>왜 선돈오후점수(先頓悟後漸修)인가?</strong> &quot;미망으로부터 깨어나는 것은 갑작스러우나 범부로부터 성인이 되는 것은 점차적이다&quot;, &quot;바람은 그치나 물결은 여전히 솟구친다&quot;, &quot;얼음이 본래 물이었다는 사실을 알았다고 하더라도, 얼음이 실제로 물이 되는 데는 따뜻한 햇빛을 받을 시간이 필요하다&quot; — 이 비유들은 모두 앎(인식)과 행위(실천) 사이의 간극을 메우기 위해 점수가 반드시 필요함을 보여줌.</p><p><strong>정혜쌍수</strong>: **정(定, samatha)**은 어지러운 마음을 한곳에 집중해 모든 경계상을 허물고 마음을 고요하게 함으로써 분별지를 제거하는 것(선종이 선호). **혜(慧, vipasyana)**는 제법무자성·공성, 인무아·법무아, 자심본성을 직관하는 것(교종/반야가 선호). 정 없는 혜는 들떠서 공론이 되고, 혜 없는 정은 어둡고 막힌다 — 정은 번뇌의 작동을 멈춰 지혜가 솟는 틈을 열어주고, 혜는 그 틈에서 법의 실상을 꿰뚫어 집착의 뿌리를 끊는다.</p><p><strong>간화경절문</strong>: 화두는 말을 끊기 위해 말로써 말을 부수는 도구다. 교를 통해 선으로 들어갔다 하더라도 선은 거기서 멈추면 안 되는데, 강 저편에 다다른 수행자가 타고 간 뗏목(교의 언어)을 버려야 하는 것과 같다. 다만 이 &#39;버림&#39;이 뗏목을 타는 일 못지않게 힘들기 때문에, 그를 위한 별도의 방법으로 **화두 공부(간화선)**가 필요함. 뛰어난 능력을 지닌 상근기의 사람은 언교(言敎)에 의존하지 않고도 처음부터 바로 진심을 체득할 수 있는데, 이 지름길이 곧 경절문이며 오직 간화선을 통해서만 가능함.</p><p>정리하면, 하근기·중근기는 무명 → <strong>해오</strong>(마음의 체는 고요하고 공적영지가 나에게도 있음을 앎) → 앎과 실천 사이의 괴리 발생 → <strong>점수</strong>(정혜쌍수) → 화두 → <strong>증오</strong>의 경로(원돈신해문 → 성적등지문 → 간화경절문)를 밟고, 상근기는 무명에서 곧바로 화두를 통해 증오에 이르는(간화경절문) 지름길을 밟는다.</p><h2 id="이후-조선-불교" tabindex="-1">이후 조선 불교 <a class="header-anchor" href="#이후-조선-불교" aria-label="Permalink to &quot;이후 조선 불교&quot;">​</a></h2><p>조선은 숭유억불 정책을 실시했으나 왕실에서는 여전히 불교가 유행함(봉은사·봉국사·봉선사처럼 &#39;奉&#39; 자가 붙은 사찰은 대개 왕실의 불사를 받드는 절이었음). 승과·승계 제도는 폐지되었다가 문정왕후 수렴청정기에 잠시 복원(서산대사·사명대사가 활동). 일부에서는 유교와의 습합이 이루어졌는데, 부모의 은혜를 강조하는 『부모은중경』이 대표적이며, 불교의 오계(五戒)를 유가의 오상(仁·義·禮·智·信)에 대응시켜 설명하기도 함 — 불살생=인, 불투도=의, 불사음=예, 불망어=신, 불음주=지.</p>',25)])])}const q=o(a,[["render",e]]);export{d as __pageData,q as default};
